import{_ as i,c as t,o as s,a3 as n}from"./chunks/framework.Cc9k46oU.js";const g=JSON.parse('{"title":"Troubleshooting Linux Electron Debug Crash (ENOSPC inotify Watcher Limit Exceeded)","description":"Root cause analysis and permanent sysctl tuning guide for ENOSPC (System limit for number of file watchers reached) kernel inotify limit errors when debugging Electron applications on Linux.","frontmatter":{"title":"Troubleshooting Linux Electron Debug Crash (ENOSPC inotify Watcher Limit Exceeded)","description":"Root cause analysis and permanent sysctl tuning guide for ENOSPC (System limit for number of file watchers reached) kernel inotify limit errors when debugging Electron applications on Linux.","head":[["meta",{"name":"keywords","content":"SyncETA, Electron, Linux, ENOSPC, inotify, max_user_watches, max_user_instances, chokidar, debugging, troubleshooting"}],["meta",{"property":"og:title","content":"Troubleshooting Linux Electron Debug Crash (ENOSPC inotify Watcher Limit Exceeded) | Empasy Docs"}],["meta",{"property":"og:description","content":"Guide to resolving Electron dev server crashes by increasing the Linux kernel fs.inotify.max_user_watches limit or falling back to CHOKIDAR_USEPOLLING."}],["meta",{"property":"og:image","content":"https://doc.empasy.com/images/favicon.png"}],["meta",{"property":"og:url","content":"https://doc.empasy.com/en/logs/20250827_debugCrash"}],["link",{"rel":"canonical","href":"https://doc.empasy.com/en/logs/20250827_debugCrash"}],["link",{"rel":"alternate","hreflang":"ko","href":"https://doc.empasy.com/logs/20250827_debugCrash"}],["link",{"rel":"alternate","hreflang":"en","href":"https://doc.empasy.com/en/logs/20250827_debugCrash"}],["link",{"rel":"alternate","hreflang":"ja","href":"https://doc.empasy.com/ja/logs/20250827_debugCrash"}],["link",{"rel":"alternate","hreflang":"x-default","href":"https://doc.empasy.com/logs/20250827_debugCrash"}],["meta",{"property":"og:type","content":"article"}],["meta",{"property":"og:site_name","content":"Empasy Docs"}],["meta",{"property":"og:title","content":"Troubleshooting Linux Electron Debug Crash (ENOSPC inotify Watcher Limit Exceeded) | Empasy Docs"}],["meta",{"property":"og:description","content":"Root cause analysis and permanent sysctl tuning guide for ENOSPC (System limit for number of file watchers reached) kernel inotify limit errors when debugging Electron applications on Linux."}],["meta",{"property":"og:url","content":"https://doc.empasy.com/en/logs/20250827_debugCrash"}],["meta",{"name":"twitter:card","content":"summary_large_image"}],["meta",{"name":"twitter:title","content":"Troubleshooting Linux Electron Debug Crash (ENOSPC inotify Watcher Limit Exceeded) | Empasy Docs"}],["meta",{"name":"twitter:description","content":"Root cause analysis and permanent sysctl tuning guide for ENOSPC (System limit for number of file watchers reached) kernel inotify limit errors when debugging Electron applications on Linux."}]],"sort":400},"headers":[],"relativePath":"en/logs/20250827_debugCrash.md","filePath":"en/logs/20250827_debugCrash.md","lastUpdated":1795293539000}'),a={name:"en/logs/20250827_debugCrash.md"};function r(o,e,l,h,c,d){return s(),t("div",null,[...e[0]||(e[0]=[n(`<h1 id="troubleshooting-linux-electron-debug-crash-enospc-system-limit-for-number-of-file-watchers-reached" tabindex="-1">Troubleshooting Linux Electron Debug Crash (<code>ENOSPC: System limit for number of file watchers reached</code>) <a class="header-anchor" href="#troubleshooting-linux-electron-debug-crash-enospc-system-limit-for-number-of-file-watchers-reached" aria-label="Permalink to “Troubleshooting Linux Electron Debug Crash (ENOSPC: System limit for number of file watchers reached)”">​</a></h1><h2 id="_1-symptoms-and-root-cause-analysis-rca" tabindex="-1">1. Symptoms and Root Cause Analysis (RCA) <a class="header-anchor" href="#_1-symptoms-and-root-cause-analysis-rca" aria-label="Permalink to “1. Symptoms and Root Cause Analysis (RCA)”">​</a></h2><p>When running the SyncETA Electron application in debug mode (<code>yarn dev:debug</code>) in a Linux desktop development environment, the Vite/Chokidar file watcher monitors file descriptors inside <code>node_modules</code> and workspace subdirectories. This exceeds the Linux kernel&#39;s default <code>inotify</code> watcher limit (<code>8192</code> or <code>65536</code>), causing the process to terminate abnormally with an <code>ENOSPC: System limit for number of file watchers reached</code> exception.</p><hr><h2 id="_2-solution-1-increase-the-linux-kernel-inotify-watcher-limit-recommended" tabindex="-1">2. Solution 1: Increase the Linux Kernel <code>inotify</code> Watcher Limit (Recommended) <a class="header-anchor" href="#_2-solution-1-increase-the-linux-kernel-inotify-watcher-limit-recommended" aria-label="Permalink to “2. Solution 1: Increase the Linux Kernel inotify Watcher Limit (Recommended)”">​</a></h2><h3 id="_2-1-check-current-kernel-values" tabindex="-1">2.1 Check Current Kernel Values <a class="header-anchor" href="#_2-1-check-current-kernel-values" aria-label="Permalink to “2.1 Check Current Kernel Values”">​</a></h3><div class="language-bash"><button title="Copy code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">cat</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /proc/sys/fs/inotify/max_user_watches</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">cat</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /proc/sys/fs/inotify/max_user_instances</span></span></code></pre></div><h3 id="_2-2-apply-immediately-at-runtime-temporary" tabindex="-1">2.2 Apply Immediately at Runtime (Temporary) <a class="header-anchor" href="#_2-2-apply-immediately-at-runtime-temporary" aria-label="Permalink to “2.2 Apply Immediately at Runtime (Temporary)”">​</a></h3><div class="language-bash"><button title="Copy code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> sysctl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> fs.inotify.max_user_watches=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">524288</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> sysctl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> fs.inotify.max_user_instances=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">1024</span></span></code></pre></div><h3 id="_2-3-apply-permanently-etc-sysctl-d-99-inotify-conf" tabindex="-1">2.3 Apply Permanently (<code>/etc/sysctl.d/99-inotify.conf</code>) <a class="header-anchor" href="#_2-3-apply-permanently-etc-sysctl-d-99-inotify-conf" aria-label="Permalink to “2.3 Apply Permanently (/etc/sysctl.d/99-inotify.conf)”">​</a></h3><p>Register a <code>sysctl.d</code> configuration file so that the settings persist across system reboots.</p><div class="language-bash"><button title="Copy code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">echo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;fs.inotify.max_user_watches=524288&#39;</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> |</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> tee</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /etc/sysctl.d/99-inotify.conf</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">echo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;fs.inotify.max_user_instances=1024&#39;</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> |</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> tee</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -a</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /etc/sysctl.d/99-inotify.conf</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> sysctl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -p</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /etc/sysctl.d/99-inotify.conf</span></span></code></pre></div><p>After applying the configuration, re-run <code>yarn dev:debug</code> to verify normal startup.</p><hr><h2 id="_3-solution-2-switch-to-polling-mode-when-kernel-parameters-cannot-be-modified-containers-restricted-environments" tabindex="-1">3. Solution 2: Switch to Polling Mode When Kernel Parameters Cannot Be Modified (Containers / Restricted Environments) <a class="header-anchor" href="#_3-solution-2-switch-to-polling-mode-when-kernel-parameters-cannot-be-modified-containers-restricted-environments" aria-label="Permalink to “3. Solution 2: Switch to Polling Mode When Kernel Parameters Cannot Be Modified (Containers / Restricted Environments)”">​</a></h2><p>In CI container environments without <code>sudo</code> privileges or where modifying kernel parameters is restricted, enable polling mode instead of relying on filesystem events.</p><h3 id="_3-1-one-time-environment-variable-execution" tabindex="-1">3.1 One-Time Environment Variable Execution <a class="header-anchor" href="#_3-1-one-time-environment-variable-execution" aria-label="Permalink to “3.1 One-Time Environment Variable Execution”">​</a></h3><div class="language-bash"><button title="Copy code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">CHOKIDAR_USEPOLLING</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">1</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> CHOKIDAR_INTERVAL</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">800</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> yarn</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> dev:debug</span></span></code></pre></div><h3 id="_3-2-register-in-ide-run-debug-configuration" tabindex="-1">3.2 Register in IDE Run/Debug Configuration <a class="header-anchor" href="#_3-2-register-in-ide-run-debug-configuration" aria-label="Permalink to “3.2 Register in IDE Run/Debug Configuration”">​</a></h3><p>You can apply these settings permanently in IntelliJ IDEA by adding the following variables under <strong>Run/Debug Configurations -&gt; Environment variables</strong>:</p><table tabindex="0"><thead><tr><th style="text-align:left;">Environment Variable Key</th><th style="text-align:left;">Recommended Value</th><th style="text-align:left;">Description</th></tr></thead><tbody><tr><td style="text-align:left;"><code>CHOKIDAR_USEPOLLING</code></td><td style="text-align:left;"><code>1</code></td><td style="text-align:left;">Enables periodic file state polling instead of OS kernel <code>inotify</code></td></tr><tr><td style="text-align:left;"><code>CHOKIDAR_INTERVAL</code></td><td style="text-align:left;"><code>800</code></td><td style="text-align:left;">File change detection polling interval (in <code>ms</code>, minimizing CPU overhead)</td></tr></tbody></table>`,21)])])}const m=i(a,[["render",r]]);export{g as __pageData,m as default};
